import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = [0] * (n + 2)
    a[0] = n + 1
    for k in range(1, len(data), 2):
        a[data[k]] = data[k + 1]

    # A path lists all isolated balls in the final set, in x order.
    # Its consecutive vertices must have a rectangle with no isolated ball.
    dp = [0] * (n + 2)
    dp[0] = 1
    for j in range(1, n + 2):
        low = a[j]
        total = 0
        for i in range(j):
            high = a[i]
            if high <= low or dp[i] == 0:
                continue

            vals = []
            for k in range(i + 1, j):
                v = a[k]
                if low < v < high:
                    vals.append(v)

            # An isolated point is both a prefix minimum and suffix maximum.
            mx = 0
            candidates = []
            for v in reversed(vals):
                if v > mx:
                    candidates.append(v)
                    mx = v

            mn = n + 1
            p = len(candidates) - 1
            good = True
            for v in vals:
                if p >= 0 and v == candidates[p]:
                    if v < mn:
                        good = False
                        break
                    p -= 1
                if v < mn:
                    mn = v
            if good:
                total += dp[i]
        dp[j] = total % MOD

    print(dp[n + 1])


if __name__ == '__main__':
    solve()

