import sys
from collections import deque

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1
    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n
    while q:
        u = q.popleft()
        v = a[u]
        child = dp[u]
        parent = dp[v]
        dp[u] = None
        if child is None:
            if parent is None:
                dp[v] = list(range(1, m + 1))
            else:
                for j in range(m):
                    parent[j] = parent[j] * (j + 1) % MOD
        else:
            s = 0
            if parent is None:
                for j in range(m):
                    s = (s + child[j]) % MOD
                    child[j] = s
                dp[v] = child
            else:
                for j in range(m):
                    s = (s + child[j]) % MOD
                    parent[j] = parent[j] * s % MOD
        deg[v] -= 1
        if deg[v] == 0:
            q.append(v)
    answer = 1
    for start in range(n):
        if deg[start] == 0:
            continue
        u = start
        product = None
        while deg[u]:
            deg[u] = 0
            row = dp[u]
            if row is not None:
                if product is None:
                    product = row
                else:
                    for j in range(m):
                        product[j] = product[j] * row[j] % MOD
            u = a[u]
        ways = m if product is None else sum(product) % MOD
        answer = answer * ways % MOD
    print(answer)

if __name__ == '__main__':
    solve()

