import sys

MOD = 998244353


def solve(n, a):
    events = {}
    for i, x in enumerate(a, 1):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                events.setdefault(p, []).append((i, e))
            p += 1
        if x > 1:
            events.setdefault(x, []).append((i, 1))

    answer = 1
    for p, ev in events.items():
        if len(ev) == 1:
            i, e = ev[0]
            answer = answer * (pow(p, e * i, MOD) + pow(p, e * (n - i), MOD)) % MOD
            continue

        total = sum(e for _, e in ev)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * p % MOD

        dp = [1]
        prev = 0
        for i, e in ev:
            gap = i - prev - 1
            if gap:
                base = pow(p, gap, MOD)
                factor = 1
                for h in range(len(dp)):
                    dp[h] = dp[h] * factor % MOD
                    factor = factor * base % MOD

            ndp = [0] * (len(dp) + e)
            for h, v in enumerate(dp):
                if not v:
                    continue
                k = h + e
                ndp[k] = (ndp[k] + v * powers[k]) % MOD
                if h >= e:
                    k = h - e
                    ndp[k] = (ndp[k] + v * powers[k]) % MOD
                else:
                    ndp[0] = (ndp[0] + v * pow(p, i * (e - h), MOD)) % MOD
            dp = ndp
            prev = i

        gap = n - 1 - prev
        if gap:
            base = pow(p, gap, MOD)
            factor = 1
            s = 0
            for v in dp:
                s = (s + v * factor) % MOD
                factor = factor * base % MOD
        else:
            s = sum(dp) % MOD
        answer = answer * s % MOD
    return answer


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    print(solve(data[0], data[1:]))


