    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    m = max(a)
    mod = 998244353
    freq = [0] * (m + 1)
    for x in a:
        freq[x] += 1
    phi = list(range(m + 1))
    ds = [[] for _ in range(m + 1)]
    for d in range(1, m + 1):
        if d > 1 and phi[d] == d:
            for j in range(d, m + 1, d):
                phi[j] -= phi[j] // d
        for j in range(d, m + 1, d):
            if freq[j]:
                ds[j].append(d)
    vals = [x for x in range(1, m + 1) if freq[x]]
    heavy = [x for x in vals if freq[x] * len(ds[x]) > n * 1.5]
    ish = [False] * (m + 1)
    for x in heavy:
        ish[x] = True
    weights = [0] * n
    w = 1
    for i in range(n):
        weights[i] = w
        w = w * 2 % mod
    add = [0] * n
    sums = [0] * (m + 1)
    for x in vals:
        if not ish[x]:
            ds[x] = [(d, phi[d]) for d in ds[x]]
    for i, x in enumerate(a):
        if not ish[x]:
            s = 0
            w = weights[i]
            for d, p in ds[x]:
                s += p * sums[d]
                sums[d] += w
            add[i] = s % mod
    all_heavy = len(heavy) == len(vals)
    for h in heavy:
        gs = [0] * (m + 1)
        for x in vals:
            gs[x] = gcd(x, h)
        sh = 0
        if all_heavy:
            for i, x in enumerate(a):
                add[i] += gs[x] * sh
                if x == h:
                    sh += weights[i]
        else:
            sl = 0
            for i, x in enumerate(a):
                if x == h:
                    add[i] += h * sh + sl
                    sh += weights[i]
                else:
                    g = gs[x]
                    add[i] += g * sh
                    if not ish[x]:
                        sl += g * weights[i]
    ans = 0
    out = []
    for s in add:
        ans = (ans * 2 + s) % mod
        out.append(str(ans))
    sys.stdout.write('\n'.join(out))


