class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 1000000007
        limit = min(n, x)
        dp = [0] * (limit + 1)
        dp[0] = 1
        factors = [((x - k + 1) * y) % mod for k in range(limit + 1)]
        for i in range(1, n + 1):
            for k in range(min(i, limit), 0, -1):
                dp[k] = (k * dp[k] + factors[k] * dp[k - 1]) % mod
            dp[0] = 0
        return sum(dp) % mod

