class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        # depth[x] is the number of operations required to reach 1.
        depth = [0] * (length + 1)
        for x in range(2, length + 1):
            depth[x] = 1 + depth[x.bit_count()]
        good = [False] + [depth[x] < k for x in range(1, length + 1)]

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % mod
        invfact = [1] * (length + 1)
        invfact[length] = pow(fact[length], mod - 2, mod)
        for i in range(length, 0, -1):
            invfact[i - 1] = invfact[i] * i % mod

        ans = 0
        prefix = 0
        for i, bit in enumerate(s):
            if bit == '1':
                # First differ from s here by choosing zero.
                remaining = length - i - 1
                subtotal = 0
                for j in range(remaining + 1):
                    if good[prefix + j]:
                        subtotal += invfact[j] * invfact[remaining - j] % mod
                ans = (ans + fact[remaining] * subtotal) % mod
                prefix += 1
        return ans

