import random, time

def fast(a):
    n = len(a)
    half = n // 2
    i = 0
    for j in range(half, n):
        if i == half:
            break
        if 2 * a[i] <= a[j]:
            i += 1
    return i

def brute(a):
    @lru_cache(None)
    def f(mask):
        if not mask:
            return 0
        bit = mask & -mask
        i = bit.bit_length() - 1
        rest = mask ^ bit
        best = f(rest)
        for j in range(i + 1, len(a)):
            if rest >> j & 1 and 2 * a[i] <= a[j]:
                best = max(best, 1 + f(rest ^ (1 << j)))
        return best
    return f((1 << len(a)) - 1)

