class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        g = [[-1] * (m + 2)]
        g.extend([[-1] + row + [-1] for row in grid])
        g.append([-1] * (m + 2))
        directions = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        answer = 0
        for k, (dr, dc) in enumerate(directions):
            prefix = [[0] * (m + 2) for _ in range(n + 2)]
            rows = range(1, n + 1) if dr == 1 else range(n, 0, -1)
            for r in rows:
                current, previous, values = prefix[r], prefix[r - dr], g[r]
                for c in range(1, m + 1):
                    v = values[c]
                    if v == 1:
                        current[c] = 1
                    else:
                        p = previous[c - dc]
                        if p and ((v == 2 and p & 1) or (v == 0 and not p & 1)):
                            current[c] = p + 1
            tr, tc = directions[(k + 1) % 4]
            rows = range(n, 0, -1) if tr == 1 else range(1, n + 1)
            following = [0] * (m + 2)
            for r in rows:
                current = [0] * (m + 2)
                values, next_values, pref = g[r], g[r + tr], prefix[r]
                for c in range(1, m + 1):
                    v = values[c]
                    wanted = 2 if v == 1 else 2 - v
                    s = following[c + tc] + 1 if next_values[c + tc] == wanted else 1
                    current[c] = s
                    if pref[c]:
                        length = pref[c] + s - 1
                        if length > answer:
                            answer = length
                following = current
        return answer

