import sys
from math import comb


def fwht(a):
    n = len(a)
    step = 1
    while step < n:
        jump = step * 2
        for start in range(0, n, jump):
            for i in range(start, start + step):
                x = a[i]
                y = a[i + step]
                a[i] = x + y
                a[i + step] = x - y
        step = jump


def solve(w, rows):
    d = w - 1
    n = 1 << d
    full = (1 << w) - 1
    a = [0] * n
    for x in rows:
        if x >= n:
            x ^= full
        a[x] += 1

    eig = []
    for s in range(d + 1):
        val = 0
        for j in range(s + 1):
            c = comb(s, j) * (-1 if j & 1 else 1)
            for k in range(d - s + 1):
                t = j + k
                val += c * comb(d - s, k) * min(t, w - t)
        eig.append(val)

    fwht(a)
    for i in range(n):
        a[i] *= eig[i.bit_count()]
    fwht(a)
    return min(a) // n


