import sys
import heapq


def scores(values):
    low = []
    high = []
    sl = sh = 0
    result = [0]
    push = heapq.heappush
    pop = heapq.heappop
    for i, x in enumerate(values, 1):
        if not low or x <= -low[0]:
            push(low, -x)
            sl += x
        else:
            push(high, x)
            sh += x
        if len(low) > len(high) + 1:
            y = -pop(low)
            sl -= y
            sh += y
            push(high, y)
        elif len(high) > len(low):
            y = pop(high)
            sh -= y
            sl += y
            push(low, -y)
        if i % 2 == 0:
            result.append(sh - sl)
    return result


def solve(a):
    n = len(a)
    m = n // 2
    if n % 2 == 0:
        b = sorted(a)
        return sum(b[m:]) - sum(b[:m])
    left = scores(a[:-1])
    right = scores(a[:0:-1])
    return max(left[k] + right[m-k] for k in range(m+1))


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    print(solve(data[1:]))


