        graph[x].append((y, z))
        graph[y].append((x, z))
    del data

    dist = [-1] * n
    for root in range(n):
        if dist[root] != -1:
            continue
        dist[root] = 0
        nodes = [root]
        mask = 0
        for v in nodes:
            dv = dist[v]
            for w, z in graph[v]:
                value = dv ^ z
                if dist[w] == -1:
                    dist[w] = value
                    mask |= value
                    nodes.append(w)
