        size = len(nodes)
        for b in range(mask.bit_length()):
            bit = 1 << b
            count = sum(1 for v in nodes if dist[v] & bit)
            if count * 2 > size:
                flip |= bit
        if flip:
            for v in nodes:
                dist[v] ^= flip

    print(' '.join(map(str, dist)))


