import sys, heapq

def calc(items,W):
    groups={}
    for w,v in items:
        if v>1: groups.setdefault(w,[]).append(1-v)
    dp=[0]*(W+1)
    for w,heap in groups.items():
        heapq.heapify(heap)
        pref=[0]
        for _ in range(W//w):
            x=heap[0]
            if x>=0: break
            pref.append(pref[-1]-x)
            heapq.heapreplace(heap,x+2)
        K=len(pref)-1
        if K<=8:
            for k in range(1,K+1):
                gain=pref[k]-pref[k-1]
                for s in range(W,w-1,-1):
                    z=dp[s-w]+gain
                    if z>dp[s]: dp[s]=z
            continue
        for r in range(w):
            a=dp[r::w]
            m=len(a)-1
            if not m: continue
            stack=[(1,m,0,m)]
            while stack:
                lo,hi,ol,oh=stack.pop()
                mid=(lo+hi)//2
                start=max(ol,mid-K)
                end=min(mid,oh)
                best=-1
                arg=start
                for j in range(start,end+1):
                    z=a[j]+pref[mid-j]
                    if z>best:
                        best=z; arg=j
                dp[r+mid*w]=best
                if lo<mid: stack.append((lo,mid-1,ol,arg))
                if mid<hi: stack.append((mid+1,hi,arg,oh))
    return dp[W]

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n,W=data[:2]
    items=list(zip(data[2::2],data[3::2]))
    print(calc(items,W))

