import sys


def possible(s, t, k):
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False

    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        return True

    # On diagonal d = x - y, store the furthest reachable x.
    prev = {0: x}
    for cost in range(1, k + 1):
        cur = {}
        for d in range(-cost, cost + 1):
            best = -1

            # Replace a character.
            p = prev.get(d, -1)
            if p >= 0 and p < n and p - d < m:
                best = p + 1

            # Delete a character of s.
            p = prev.get(d - 1, -1)
            if p >= 0 and p < n:
                best = max(best, p + 1)

            # Insert a character into s.
            p = prev.get(d + 1, -1)
            if p >= 0 and p - d - 1 < m:
                best = max(best, p)

            if best < 0:
                continue
            x = best
            y = x - d
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            cur[d] = x
        prev = cur
    return False


def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    print('Yes' if possible(data[1], data[2], k) else 'No')


if __name__ == '__main__':
