from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Each subtree occupies one interval in the full postorder string.
        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            v = stack.pop()
            if v >= 0:
                start[v] = len(order)
                stack.append(~v)
                stack.extend(reversed(children[v]))
            else:
                v = ~v
                order.append(s[v])
                end[v] = len(order)

        # Manacher's algorithm, with separators handling both parities.
        text = '^#' + '#'.join(order) + '#$'
        radius = [0] * len(text)
        center = right = 0
        for i in range(1, len(text) - 1):
            if i < right:
                radius[i] = min(right - i, radius[2 * center - i])
            k = radius[i]
            while text[i - k - 1] == text[i + k + 1]:
                k += 1
            radius[i] = k
            if i + k > right:
                center, right = i, i + k

        return [
            radius[start[v] + end[v] + 1] >= end[v] - start[v]
