class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)
        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            v = stack.pop()
            if v >= 0:
                start[v] = len(order)
                stack.append(~v)
                stack.extend(reversed(children[v]))
            else:
                v = ~v
                order.append(s[v])
                end[v] = len(order)
        text = '^#' + '#'.join(order) + '#$'
        radius = [0] * len(text)
        center = right = 0
        for i in range(1, len(text) - 1):
