def convolution(a,b):
    a=np.asarray(a,dtype=np.int64)
    b=np.asarray(b,dtype=np.int64)
    size=1<<(len(a)+len(b)-2).bit_length()
    al=np.fft.rfft(a&32767,size)
    ah=np.fft.rfft(a>>15,size)
    bl=np.fft.rfft(b&32767,size)
    bh=np.fft.rfft(b>>15,size)
    lo=np.rint(np.fft.irfft(al*bl,size)).astype(np.int64)%MOD
    hi=np.rint(np.fft.irfft(ah*bh,size)).astype(np.int64)%MOD
    mid=np.rint(np.fft.irfft(al*bh+ah*bl,size)).astype(np.int64)%MOD
    return (lo+(mid<<15)+hi*(1<<30))%MOD

def solve(n,s):
    if s[0]!=66 or s[-1]!=87:
        return 0
    b=[0]*(n+1)
    w=black=0
    for c in s:
        if c==66:
            black+=1
        else:
            w+=1
            b[w]=black
    f=[1]*(n+1)
    for i in range(1,n+1):
        f[i]=f[i-1]*i%MOD
    inv=[1]*(n+1)
    inv[n]=pow(f[n],MOD-2,MOD)
    for i in range(n,0,-1):
        inv[i-1]=inv[i]*i%MOD
    v=f.copy()
    d=[0]*(n+1)
    def cdq(l,r):
        if r-l<32:
            for i in range(l,r+1):
                if b[i]>i:
                    continue
                x=v[i]*inv[i-b[i]]%MOD
                d[i]=x
                if x:
                    for j in range(i+1,r+1):
                        if b[j]<=j:
                            v[j]=(v[j]-x*f[j-b[i]])%MOD
            return
        m=(l+r)//2
        cdq(l,m)
        src={}
