from collections import deque
import random

def fast(n, edges):
    adj=[[] for _ in range(n)]
    for a,b in edges: adj[a].append(b)
    dist=[-1]*n; dist[0]=0; q=deque([0])
    while q:
        u=q.popleft(); nd=dist[u]+1
        for v in adj[u]:
            if v==0: return nd
            if dist[v]==-1:
                dist[v]=nd; q.append(v)
    return -1

def brute(n,edges):
    adj=[[] for _ in range(n)]
    for a,b in edges: adj[a].append(b)
    best=n+1
    def dfs(u, seen, depth):
        nonlocal best
        for v in adj[u]:
            if v==0: best=min(best,depth+1)
            elif v not in seen: dfs(v,seen|{v},depth+1)
    dfs(0,{0},0)
    return best if best<=n else -1
