class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        transitions = []
        for a, b in states:
            predecessors = [i for i, (c, d) in enumerate(states) if a != c and b != d]
            transitions.append((a, b, *predecessors))
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]
        for k in range(1, n // 2):
            left, right = cost[k], cost[n - 1 - k]
            dp = [left[a] + right[b] + min(dp[x], dp[y], dp[z])
                  for a, b, x, y, z in transitions]
        return min(dp)

