def brute(s):
    t = '1' + s + '1'
    best = s.count('1')
    for i in range(1, len(t)-1):
        for j in range(i+1, len(t)):
            if t[i:j] != '1'*(j-i) or t[i-1] != '0' or t[j] != '0':
                continue
            u = t[:i] + '0'*(j-i) + t[j:]
            for a in range(1, len(u)-1):
                for b in range(a+1, len(u)):
                    if u[a:b] == '0'*(b-a) and u[a-1] == u[b] == '1':
                        best = max(best, u.count('1')-2 + b-a)
    return best
