def brute(s):
    marked = [False] * len(s)
    score = 0
    for i in range(len(s)):
        for j in range(i - 1, -1, -1):
            if not marked[j] and ord(s[i]) + ord(s[j]) == ord('a') + ord('z'):
                marked[i] = marked[j] = True
                score += i - j
                break
    return score

