class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        bits = {'a': 1, 'e': 2, 'i': 4, 'o': 8, 'u': 16}
        answer = 0
        for left in range(len(word)):
            mask = 0
            consonants = 0
            for right in range(left, len(word)):
                bit = bits.get(word[right], 0)
                if bit:
                    mask |= bit
                else:
                    consonants += 1
                if consonants > k:
                    break
                if mask == 31 and consonants == k:
                    answer += 1
        return answer

